// O(n log k): (value, index) pairs in a red-black tree
var set = new SortedSet<(int val, int idx)>();
var res = new int[nums.Length - k + 1];
for (int i = 0; i < nums.Length; i++) {
    set.Add((nums[i], i));                          // the index makes the pairs distinct
    if (i >= k) set.Remove((nums[i - k], i - k));   // left the window
    if (i >= k - 1) res[i - k + 1] = set.Max.val;
}

